local COLOR_PREFABS = {
    WHITE = 'StarAreaWhitePrefab',
    GREEN = 'StarAreaGreenPrefab',
    RED = 'StarAreaRedPrefab',
    YELLOW = 'StarAreaYellowPrefab',
}

local HALF_CIRCLE = 180

---@type TrailBattleMgr
local TrailBattleMgr = import('Game.TrailBattle.TrailBattleMgr')

