---@class TrailMapCore
---@field StarAreaYellowPrefab            UnityEngine.Transform
---@field StarAreaRedPrefab                UnityEngine.Transform
---@field StarAreaGreenPrefab            UnityEngine.Transform
---@field StarAreaWhitePrefab            UnityEngine.Transform @画起始区白线
---@field Building                        UnityEngine.Transform @建筑点
---@field CircleLineRender                UnityEngine.Transform @根节点
---@field LineDrawer                UnityEngine.Transform @子元素的画线节点s
---@field MainCamera                    UnityEngine.Transform @像机节点
local TrailMapCore = Class('TrailMapCore')

local CONSTANTS = {
    DELTA_X = 116, ---相对ui的圆心
    DELTA_Y = 1700,
    ANGLE_MIN = -20,
    ANGLE_MAX = 180,
    ANGLE_SPAN = 20,
}

function TrailMapCore:__init()
    self.behaviourAction = nil
    self.quickSwipe = nil
    self.angleMove = 0
    self.startTime = 0
    self.snap = 0
    self.velocity = 0 ---速度
    self.isRight = false
    self.isRunning = true
    self.isDragging = false
    self.isQuickDragging = false
    self.startAngle = -2
    self.levelUpStartAngle = 0
    self.levelStayStartAngle = 0
    self.levelDownStartAngle = 0
end

function TrailMapCore:__delete()
    self.behaviourAction = nil
    self.quickSwipe = nil
    self.angleMove = nil
    self.velocity = nil
    self.snap = nil
    self.isDragging = nil
    self.isQuickDragging = false
end

function TrailMapCore:Awake()
    trailBattleMgr = TrailBattleMgr:GetInstance()
    
    local quickSwipe = KTool.GetOrAddComponent(self.MainCamera.gameObject, typeof(QuickSwipe))
    quickSwipe.swipeDirection = 1 -- Horizontal ---只添加水平方向上的swipe的逻辑
    quickSwipe.onSwipeAction:AddListener(Bind(self, self.OnSwipeActionEvent))
    self.quickSwipe = quickSwipe
end

function TrailMapCore:Start()
    ---画初始起始区的线
    self:DrawWhiteArc(630, 91)
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        --behaviourAction.UpdateAction = Bind(self, self.OnUpdate)
        behaviourAction.UpdateAction = function()
            self:OnUpdate()
        end
        self.behaviourAction = behaviourAction
    end
end

---UpdateCircle
---更新圆环
function TrailMapCore:UpdateCircle()
    local segmentVo = trailBattleMgr:GetSegmentRewardVoByRefId((trailBattleMgr:GetMySegment()))
    local segmentSpanUp, segmentSpanStay, segmentSpanDown = 0, 0, 0
    if segmentVo.upGrade ~= 0 then
        segmentSpanUp = checkInt(segmentVo.upGrade[2]) -checkInt(segmentVo.upGrade[1]) + 1
    end
    if segmentVo.keepGrade ~= 0 then
        segmentSpanStay = checkInt(segmentVo.keepGrade[2]) - checkInt(segmentVo.keepGrade[1]) + 1
    end
    if segmentVo.downGrade ~= 0 then
        segmentSpanDown = checkInt(segmentVo.downGrade[2]) - checkInt(segmentVo.downGrade[1]) + 1
    end


    local deltaAngle = HALF_CIRCLE / (segmentSpanUp + segmentSpanStay + segmentSpanDown)
    if deltaAngle > 0 then
        local flagTrans = self.CircleLineRender.transform:Find('StartFlag')
        if segmentSpanUp > 0 then
            local go = KTool.Instantiate(self.LineDrawer.gameObject, flagTrans.gameObject, false)
            local angle = HALF_CIRCLE
            local x = Mathf.Sin(Mathf.Deg2Rad * angle) * TrailBattleMgr.CONSTANTS.DELTA_Y / 100
            local y = Mathf.Cos(Mathf.Deg2Rad * angle) * TrailBattleMgr.CONSTANTS.DELTA_Y / 100
            go.transform.localPosition = Vector3.New(x, y, 0)
            go.transform:SetRotationZ(-angle)

            local start = (HALF_CIRCLE - segmentSpanUp * deltaAngle) * 2 + 1
            local len = HALF_CIRCLE * 2 - start + 1
            self.levelUpStartAngle = math.floor(start * 0.5) + 5
            self:DrawYellowArc(start, len)
        end
        if segmentSpanStay > 0 then
            local go = KTool.Instantiate(self.LineDrawer.gameObject, flagTrans.gameObject, false)
            local angle = (segmentSpanDown + segmentSpanStay) * deltaAngle
            local x = Mathf.Sin(Mathf.Deg2Rad * angle) * TrailBattleMgr.CONSTANTS.DELTA_Y / 100
            local y = Mathf.Cos(Mathf.Deg2Rad * angle) * TrailBattleMgr.CONSTANTS.DELTA_Y / 100
            go.transform.localPosition = Vector3.New(x, y, 0)
            go.transform:SetRotationZ(-angle)
            local start = (HALF_CIRCLE - (segmentSpanUp + segmentSpanStay) * deltaAngle) * 2 + 1
            local len = (HALF_CIRCLE - (segmentSpanUp) * deltaAngle) * 2 - start + 1
            self.levelStayStartAngle = math.floor(start * 0.5) + 5
            self:DrawGreenArc(start, len)
        end
        if segmentSpanDown > 0 then
            local go = KTool.Instantiate(self.LineDrawer.gameObject, flagTrans.gameObject, false)
            local angle = segmentSpanDown * deltaAngle
            local x = Mathf.Sin(Mathf.Deg2Rad * angle) * TrailBattleMgr.CONSTANTS.DELTA_Y / 100
            local y = Mathf.Cos(Mathf.Deg2Rad * angle) * TrailBattleMgr.CONSTANTS.DELTA_Y / 100
            go.transform.localPosition = Vector3.New(x, y, 0)
            go.transform:SetRotationZ(-angle)

            local start = (HALF_CIRCLE - (segmentSpanUp + segmentSpanStay + segmentSpanDown) * deltaAngle) * 2 + 1
            local len = segmentSpanDown * deltaAngle * 2 - start + 1
            self.levelDownStartAngle = math.floor(start * 0.5) + 5
            self:DrawRedArc(start, len)
        end
    end
end

---GetRotateAngle
---获取旋转的角度
function TrailMapCore:GetRotateAngle()
    return checkNumber(self.angleMove)
end

---OnSwipeActionEvent
---@param gesture HedgehogTeam.EasyTouch.Gesture
function TrailMapCore:OnSwipeActionEvent(gesture)
    if gesture then
        --print(gesture.deltaPosition)
        if gesture.type == EasyTouch.EvtType.On_SwipeStart then
            self.startTime = Time.time
            self.velocity = 0
            self.isDragging = false
            self.isQuickDragging = false
        elseif gesture.type == EasyTouch.EvtType.On_Swipe then
            ---拖动中
            self.isDragging = true
            local newAngle = Vector2.Angle(gesture.position + Vector2.New(CONSTANTS.DELTA_X, CONSTANTS.DELTA_Y), gesture.position + gesture.deltaPosition + Vector2.New(CONSTANTS.DELTA_X, CONSTANTS.DELTA_Y))
            --print('----->>>',newAngle)
            if gesture.deltaPosition.x < 0 then
                ---向右方向
                self.angleMove = self.angleMove + newAngle
            else
                ---向左方向
                self.angleMove = self.angleMove - newAngle
            end
            --print('=====',self.angleMove)
        elseif gesture.type == EasyTouch.EvtType.On_SwipeEnd then
            self.isDragging = false
            ---拖动结束后
            local deltaT = (Time.time - self.startTime)
            if deltaT <= 0.3 then
                self.isQuickDragging = true
                self.velocity = Vector2.Distance(gesture.position, gesture.startPosition) / deltaT
                self.snap = self.velocity / 100
                self.isRight = (gesture.startPosition.x - gesture.position.x) > 0
            end
        end
    end
end

---ScrollToAngle
---@param angle number
---@param isAnimate boolean
---@param isRight boolean
function TrailMapCore:ScrollToAngle(angle, isAnimate, isRight)
    isAnimate = checkBool(isAnimate)
    isRight = checkBool(isRight)
    if checkInt(angle) > 300 then
        angle = angle - HALF_CIRCLE * 2
    end
    self.angleMove = angle
    if isAnimate then
        self.isQuickDragging = true
        self.velocity = 120 / 0.23
        self.snap = self.velocity / 100
        self.isRight = isRight
    end
end

function TrailMapCore:OnUpdate()
    if not self.isRunning then
        return
    end
    if self.velocity > 0 then
        if self.isRight then
            self.angleMove = self.angleMove + self.velocity / 8000
        else
            self.angleMove = self.angleMove - self.velocity / 8000
        end
        self.velocity = self.velocity - self.snap
    end
    if self.isDragging then
        if self.angleMove <= (CONSTANTS.ANGLE_MIN - CONSTANTS.ANGLE_SPAN) then
            self.angleMove = CONSTANTS.ANGLE_MIN
        end
        if self.angleMove >= (CONSTANTS.ANGLE_MAX + CONSTANTS.ANGLE_SPAN) then
            self.angleMove = CONSTANTS.ANGLE_MAX
        end
    else
        if self.angleMove <= CONSTANTS.ANGLE_MIN then
            self.angleMove = CONSTANTS.ANGLE_MIN
        end
        if self.angleMove >= CONSTANTS.ANGLE_MAX then
            self.angleMove = CONSTANTS.ANGLE_MAX
        end
    end
    --if self.angleMove <= CONSTANTS.ANGLE_MIN then
    --    self.angleMove = CONSTANTS.ANGLE_MIN
    --end
    --if self.angleMove >= CONSTANTS.ANGLE_MAX then
    --    self.angleMove = CONSTANTS.ANGLE_MAX
    --end

    --local angle = Mathf.MoveTowardsAngle(self.Building.transform.eulerAngles.z, self.angleMove / 5, SPEED * Time.deltaTime)
    self.Building.transform:SetRotationZ(self.angleMove / 5)
    --self.Building.transform:SetRotationZ(angle)

    --angle = Mathf.MoveTowardsAngle(self.CircleLineRender.transform.eulerAngles.z, self.angleMove, SPEED * 6 * Time.deltaTime)
    self.CircleLineRender.transform:SetRotationZ(self.angleMove)
    --self.Building.transform:SetRotationZ(self.angleMove / 5)

    ---计算ui类型的显示与旋转
    if self.isDragging then
        trailBattleMgr:OnUpdate(self.angleMove)
        self:OnExecuteGroupChange()
    else
        ---速度拖动时
        if self.velocity >= 0 and self.isQuickDragging then
            --trailBattleMgr:OnUpdate(self.angleMove)
        else
            if self.isQuickDragging then
                self.isQuickDragging = false
                self:OnExecuteGroupChange()
            else
                self.isQuickDragging = false
            end
        end
        trailBattleMgr:OnUpdate(self.angleMove)
    end
end

function TrailMapCore:OnExecuteGroupChange()
    if self.angleMove <= self.startAngle then
        ---起始区
        Events.Broadcast(Constants.EventNames.SCROLL_CHANGE, TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.START_BUTTON)
    end
    --print(self.levelUpStartAngle, self.levelDownStartAngle, self.levelStayStartAngle)
    local judgeAngle = (self.levelStayStartAngle > 0 and (self.levelStayStartAngle - 5)) or (self.levelUpStartAngle > 0 and self.levelUpStartAngle - 5)
    local judgeUpAngle = (self.levelUpStartAngle > 0 and (self.levelUpStartAngle - 5)) or HALF_CIRCLE
    if self.levelDownStartAngle > 0 and self.angleMove >= self.levelDownStartAngle and self.angleMove <= judgeAngle then
        Events.Broadcast(Constants.EventNames.SCROLL_CHANGE, TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.DOWN_BUTTON)
    elseif self.levelStayStartAngle > 0 and (self.angleMove >= self.levelStayStartAngle and self.angleMove <= judgeUpAngle) then
        Events.Broadcast(Constants.EventNames.SCROLL_CHANGE, TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.STAY_BUTTON)
    elseif self.levelUpStartAngle > 0 and self.angleMove >= self.levelUpStartAngle then
        Events.Broadcast(Constants.EventNames.SCROLL_CHANGE, TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.UP_BUTTON)
    end
end

function TrailMapCore:RemoveColorLines()
    KTool.DestroyGameObjectChildren(self.LineDrawer.gameObject, true)
end

---DrawArc
---在区间点中划一个圆弧
---@param circleType string 圆型类别
---@param start number
---@param count number
function TrailMapCore:DrawArc(circleType, start, count)
    local go = KTool.Instantiate(self.LineDrawer.gameObject, self[tostring(circleType)].gameObject, false)
    KTool.SetActive(go, true)
    ---@type Game.Native.LineDrawer
    local lineDrawer = KTool.GetComponent(go, typeof(LineDrawer))
    lineDrawer:DrawPoints(start, count)
end

function TrailMapCore:DrawWhiteArc(start, count)
    self:DrawArc(COLOR_PREFABS.WHITE, start, count)
end
function TrailMapCore:DrawGreenArc(start, count)
    self:DrawArc(COLOR_PREFABS.GREEN, start, count)
end
function TrailMapCore:DrawRedArc(start, count)
    self:DrawArc(COLOR_PREFABS.RED, start, count)
end
function TrailMapCore:DrawYellowArc(start, count)
    self:DrawArc(COLOR_PREFABS.YELLOW, start, count)
end

function TrailMapCore:OnDestroy()
    if self.behaviourAction then
        self.behaviourAction.UpdateAction = nil
        self.behaviourAction = nil
    end
    self.quickSwipe = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TrailMapCore